from datetime import datetime
from review.out.astra_scratch.test_ronda4 import packet, base, validate_prediction

def test_corte_semanal_fijo():
    cutoff = datetime.fromisoformat('2026-09-10T02:00:00+08:00')
    try:
        p = packet(cutoff_at=cutoff)
    except ValueError:
        return
    obj = base(cutoff_at=cutoff.isoformat(), issued_at='2026-09-10T07:00:00+08:00', deadline_at=p.deadline_at.isoformat())
    assert validate_prediction(obj, p)
